}

func (r *SessionRepository) Create(ctx context.Context, session *domain.Session) error {
	const q = `
INSERT INTO sessions(user_id, token_hash, created_at, expires_at, last_seen_at)
VALUES(?, ?, ?, ?, ?)`

	result, err := r.db.ExecContext(
		ctx,
		q,
		session.UserID,
		session.TokenHash,
		session.CreatedAt.UTC().Unix(),
		session.ExpiresAt.UTC().Unix(),
		session.LastSeenAt.UTC().Unix(),
	)
	if err != nil {
		return fmt.Errorf("create session: %w", err)
	}

	id, err := result.LastInsertId()
	if err != nil {
		return fmt.Errorf("create session last insert id: %w", err)
	}
	session.ID = id
	return nil
}

func (r *SessionRepository) GetActiveByTokenHash(ctx context.Context, tokenHash string, now time.Time) (*domain.Session, *domain.User, error) {
	const q = `
SELECT
    s.id,
    s.user_id,
    s.token_hash,
    s.created_at,
    s.expires_at,
    s.last_seen_at,
    u.id,
    u.username,
    u.password_hash,
    u.role,
    u.failed_login_count,
    u.locked_until,
    u.created_at,
    u.updated_at
FROM sessions s
JOIN users u ON u.id = s.user_id
WHERE s.token_hash = ? AND s.expires_at > ?`

	var (
		session     domain.Session
		user        domain.User
		sCreatedAt  int64
		sExpiresAt  int64
		sLastSeenAt int64
		uLocked     sql.NullInt64
		uCreatedAt  int64
		uUpdatedAt  int64
	)

	err := r.db.QueryRowContext(ctx, q, tokenHash, now.UTC().Unix()).Scan(
		&session.ID,
		&session.UserID,
		&session.TokenHash,
		&sCreatedAt,
		&sExpiresAt,
		&sLastSeenAt,
		&user.ID,
		&user.Username,
		&user.PasswordHash,
		&user.Role,
		&user.FailedLoginCount,
		&uLocked,
		&uCreatedAt,
		&uUpdatedAt,
	)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, nil, repository.ErrNotFound
		}
		return nil, nil, fmt.Errorf("get active session by token hash: %w", err)
	}

	session.CreatedAt = time.Unix(sCreatedAt, 0).UTC()
	session.ExpiresAt = time.Unix(sExpiresAt, 0).UTC()
	session.LastSeenAt = time.Unix(sLastSeenAt, 0).UTC()

	if uLocked.Valid {
		t := time.Unix(uLocked.Int64, 0).UTC()
		user.LockedUntil = &t
	}
	user.CreatedAt = time.Unix(uCreatedAt, 0).UTC()
	user.UpdatedAt = time.Unix(uUpdatedAt, 0).UTC()

	return &session, &user, nil
}

func (r *SessionRepository) DeleteByTokenHash(ctx context.Context, tokenHash string) error {
	if _, err := r.db.ExecContext(ctx, `DELETE FROM sessions WHERE token_hash = ?`, tokenHash); err != nil {
		return fmt.Errorf("delete session by token hash: %w", err)
	}
	return nil
}

package sqlite

import (
	"context"
	"database/sql"
	"errors"
	"fmt"

	"clinic-admin-suite/internal/domain"
	"clinic-admin-suite/internal/repository"
)

type AuditRepository struct {
	db *sql.DB
}

func NewAuditRepository(db *sql.DB) *AuditRepository {
	return &AuditRepository{db: db}
}

func (r *AuditRepository) LastHash(ctx context.Context) (*string, error) {
	const q = `SELECT hash_self FROM audit_events ORDER BY id DESC LIMIT 1`

	var hash string
	err := r.db.QueryRowContext(ctx, q).Scan(&hash)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, nil
		}
		return nil, fmt.Errorf("audit last hash: %w", err)
	}

	return &hash, nil
}

func (r *AuditRepository) Append(ctx context.Context, event *domain.AuditEvent) error {
	const q = `
INSERT INTO audit_events(
    occurred_at,
    actor_id,
    action,
    resource_type,
    resource_id,
    before_json,
    after_json,
    request_id,
    hash_prev,
    hash_self
) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`

	var actorID sql.NullInt64
	if event.ActorID != nil {
		actorID = sql.NullInt64{Int64: *event.ActorID, Valid: true}
	}

	var beforeJSON sql.NullString
	if event.BeforeJSON != nil {
		beforeJSON = sql.NullString{String: *event.BeforeJSON, Valid: true}
	}

	var afterJSON sql.NullString
	if event.AfterJSON != nil {
		afterJSON = sql.NullString{String: *event.AfterJSON, Valid: true}
	}

	var hashPrev sql.NullString
	if event.HashPrev != nil {
		hashPrev = sql.NullString{String: *event.HashPrev, Valid: true}
	}

	result, err := r.db.ExecContext(
		ctx,
		q,
		event.OccurredAt.UTC().Unix(),
		actorID,
		event.Action,
		event.ResourceType,
		event.ResourceID,
		beforeJSON,
		afterJSON,
		event.RequestID,
		hashPrev,
		event.HashSelf,
	)
	if err != nil {
		return fmt.Errorf("append audit event: %w", err)
	}

	id, err := result.LastInsertId()
	if err != nil {
		return fmt.Errorf("append audit event last insert id: %w", err)
	}
	event.ID = id

	return nil
}

var _ repository.AuditRepository = (*AuditRepository)(nil)

package service

import (
	"errors"
	"unicode"
)

var ErrWeakPassword = errors.New("password does not meet policy requirements")

func ValidatePasswordPolicy(password string) error {
	if len(password) < 12 {
		return ErrWeakPassword
	}

	hasUpper := false
	hasLower := false
	hasDigit := false
	hasSpecial := false

	for _, r := range password {
		switch {
		case unicode.IsUpper(r):
			hasUpper = true
		case unicode.IsLower(r):
			hasLower = true
		case unicode.IsDigit(r):
			hasDigit = true
		case unicode.IsPunct(r) || unicode.IsSymbol(r):
			hasSpecial = true
		}
	}

	if !hasUpper || !hasLower || !hasDigit || !hasSpecial {
		return ErrWeakPassword
	}

	return nil
}

package service

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"strconv"
	"time"

	"clinic-admin-suite/internal/domain"
	"clinic-admin-suite/internal/repository"
)

type AuditService struct {
	auditEvents repository.AuditRepository
}

func NewAuditService(auditEvents repository.AuditRepository) *AuditService {
	return &AuditService{auditEvents: auditEvents}
}

type AuditLogInput struct {
	ActorID      *int64
	Action       string
	ResourceType string
	ResourceID   string
	Before       any
	After        any
	RequestID    string
}

func (s *AuditService) LogEvent(ctx context.Context, input AuditLogInput) error {
	var beforeJSON *string
	if input.Before != nil {
		raw, err := json.Marshal(input.Before)
		if err != nil {
			return fmt.Errorf("marshal audit before json: %w", err)
		}
		text := string(raw)
		beforeJSON = &text
	}

	var afterJSON *string
	if input.After != nil {
		raw, err := json.Marshal(input.After)
		if err != nil {
			return fmt.Errorf("marshal audit after json: %w", err)
		}
		text := string(raw)
		afterJSON = &text
	}

	hashPrev, err := s.auditEvents.LastHash(ctx)
	if err != nil {
		return fmt.Errorf("get previous audit hash: %w", err)
	}

	occurredAt := time.Now().UTC()
	hashSelf := computeAuditHash(hashPrev, occurredAt, input.ActorID, input.Action, input.ResourceType, input.ResourceID, beforeJSON, afterJSON, input.RequestID)

	event := &domain.AuditEvent{
		OccurredAt:   occurredAt,
		ActorID:      input.ActorID,
		Action:       input.Action,
		ResourceType: input.ResourceType,
		ResourceID:   input.ResourceID,
		BeforeJSON:   beforeJSON,
		AfterJSON:    afterJSON,
		RequestID:    input.RequestID,
		HashPrev:     hashPrev,
		HashSelf:     hashSelf,
	}

	if err := s.auditEvents.Append(ctx, event); err != nil {
		return fmt.Errorf("append audit event: %w", err)
	}

	return nil
}

func (s *AuditService) LogLoginSuccess(ctx context.Context, actorID int64, username, requestID, ip, userAgent string) error {
	return s.LogEvent(ctx, AuditLogInput{
		ActorID:      &actorID,
		Action:       "auth.login.success",
		ResourceType: "user",
		ResourceID:   username,
		After: map[string]any{
			"outcome":    "success",
			"ip":         ip,
			"user_agent": userAgent,
		},
		RequestID: requestID,
	})
}

func (s *AuditService) LogLoginFailure(ctx context.Context, actorID *int64, username, reason, requestID, ip, userAgent string) error {
	return s.LogEvent(ctx, AuditLogInput{
		ActorID:      actorID,
		Action:       "auth.login.failure",
		ResourceType: "user",
		ResourceID:   username,
		After: map[string]any{
			"outcome":    "failure",
			"reason":     reason,
			"ip":         ip,
			"user_agent": userAgent,
		},
		RequestID: requestID,
	})
}

func computeAuditHash(hashPrev *string, occurredAt time.Time, actorID *int64, action, resourceType, resourceID string, beforeJSON, afterJSON *string, requestID string) string {
	base := ""
	if hashPrev != nil {
		base = *hashPrev
	}

	actor := ""
	if actorID != nil {
		actor = strconv.FormatInt(*actorID, 10)
	}

	before := ""
	if beforeJSON != nil {
		before = *beforeJSON
	}

	after := ""
	if afterJSON != nil {
		after = *afterJSON
	}

	payload := base + "|" + occurredAt.Format(time.RFC3339Nano) + "|" + actor + "|" + action + "|" + resourceType + "|" + resourceID + "|" + before + "|" + after + "|" + requestID
	digest := sha256.Sum256([]byte(payload))
	return hex.EncodeToString(digest[:])
}

