+}
+
+func (s *AuthService) AuthenticateToken(ctx context.Context, rawToken string) (*domain.User, *domain.Session, error) {
+	rawToken = strings.TrimSpace(rawToken)
+	if rawToken == "" {
+		return nil, nil, ErrUnauthenticated
+	}
