+	_, err := s.users.GetByUsername(ctx, username)
+	if err == nil {
+		return nil
+	}
+	if !errors.Is(err, repository.ErrNotFound) {
+		return fmt.Errorf("check bootstrap admin user: %w", err)
+	}
