+		return handleServiceError(c, err, "Failed to discharge admission")
+	}
+
+	return httpx.OK(c, fiber.StatusOK, fiber.Map{"admission": admission})
+}
+
+func currentActorID(c *fiber.Ctx) *int64 {
+	authContext, ok := middleware.CurrentAuth(c)
