+	var (
+		item      domain.Exercise
+		createdAt int64
+		updatedAt int64
+	)
+
+	err := scanner.Scan(&item.ID, &item.Title, &item.Description, &item.Difficulty, &item.SearchText, &item.Version, &createdAt, &updatedAt)
+	if err != nil {
+		return nil, err
+	}
+
+	item.CreatedAt = time.Unix(createdAt, 0).UTC()
+	item.UpdatedAt = time.Unix(updatedAt, 0).UTC()
+
+	return &item, nil
+}
+
+func normalizeStrings(values []string) []string {
+	seen := make(map[string]struct{}, len(values))
+	out := make([]string, 0, len(values))
+	for _, raw := range values {
+		v := strings.TrimSpace(raw)
+		if v == "" {
+			continue
+		}
+		if _, ok := seen[v]; ok {
+			continue
+		}
+		seen[v] = struct{}{}
+		out = append(out, v)
+	}
+	return out
+}
