+	raw := strings.TrimPrefix(header, "bytes=")
+	if strings.Contains(raw, ",") {
+		return 0, 0, fmt.Errorf("multiple ranges not supported")
+	}
+
+	parts := strings.SplitN(raw, "-", 2)
+	if len(parts) != 2 {
+		return 0, 0, fmt.Errorf("invalid range format")
+	}
