	if err != nil {
		return httpx.Error(c, fiber.StatusInternalServerError, "INTERNAL_ERROR", "Failed to inspect media file", nil)
	}

	totalSize := info.Size()
	contentType := asset.MediaType
	if strings.TrimSpace(contentType) == "" {
