package handler

import "github.com/gofiber/fiber/v2"

type CacheUIHandler struct{}

func NewCacheUIHandler() *CacheUIHandler {
	return &CacheUIHandler{}
}

func (h *CacheUIHandler) LRUSimulator(c *fiber.Ctx) error {
	c.Type("html", "utf-8")
	return c.SendString(`
<section id="cache-lru-simulator" class="cache-simulator">
  <h3>Client LRU Cache Simulator</h3>
  <p>Simulates shared-workstation cache with limits: 2GB total or 200 items.</p>
  <form id="cache-put-form" hx-on:submit="event.preventDefault(); window.clinicCache.putFromForm();">
    <label>Item Key <input type="text" id="cache-item-key" value="exercise:1:video" /></label>
    <label>Size (bytes) <input type="number" id="cache-item-size" value="1048576" min="1" /></label>
    <label>Hash <input type="text" id="cache-item-hash" value="sha256_demo" /></label>
    <button type="submit">Cache Item</button>
  </form>
  <button type="button" onclick="window.clinicCache.render()">Refresh View</button>
  <pre id="cache-lru-output"></pre>
  <script>
  (function() {
    const MAX_BYTES = 2 * 1024 * 1024 * 1024;
    const MAX_ITEMS = 200;

    function storageKey() {
      const user = localStorage.getItem('clinic:user') || 'anonymous';
      const device = localStorage.getItem('clinic:device') || 'shared_workstation';
      return 'clinic:lru:' + user + ':' + device;
    }

    function nowISO() {
      return new Date().toISOString();
    }

    function loadIndex() {
      try {
        const raw = localStorage.getItem(storageKey());
        if (!raw) {
          return { total_bytes: 0, items: {} };
        }
        const parsed = JSON.parse(raw);
        if (!parsed || typeof parsed !== 'object') {
          return { total_bytes: 0, items: {} };
        }
        parsed.items = parsed.items || {};
        parsed.total_bytes = Number(parsed.total_bytes || 0);
        return parsed;
      } catch (err) {
        return { total_bytes: 0, items: {} };
      }
    }

    function saveIndex(index) {
      localStorage.setItem(storageKey(), JSON.stringify(index));
    }

    function recalcTotal(index) {
      index.total_bytes = Object.values(index.items).reduce((sum, item) => sum + Number(item.size_bytes || 0), 0);
      return index.total_bytes;
    }

    function evict(index) {
      recalcTotal(index);
      let entries = Object.entries(index.items);
      entries.sort((a, b) => {
        const left = new Date(a[1].last_accessed_at || a[1].created_at || 0).getTime();
        const right = new Date(b[1].last_accessed_at || b[1].created_at || 0).getTime();
        return left - right;
      });

      while (entries.length > MAX_ITEMS || index.total_bytes > MAX_BYTES) {
        const victim = entries.shift();
        if (!victim) {
          break;
        }
        const victimKey = victim[0];
        const victimSize = Number(victim[1].size_bytes || 0);
        delete index.items[victimKey];
        index.total_bytes = Math.max(0, index.total_bytes - victimSize);
      }
    }

    function putItem(key, sizeBytes, hash) {
      const index = loadIndex();
      const normalizedKey = String(key || '').trim();
      const normalizedHash = String(hash || '').trim();
      const normalizedSize = Math.max(1, Number(sizeBytes || 0));
      if (!normalizedKey || !normalizedHash || !Number.isFinite(normalizedSize)) {
        return;
      }

      const current = index.items[normalizedKey];
      if (current) {
        index.total_bytes = Math.max(0, index.total_bytes - Number(current.size_bytes || 0));
      }

      const item = {
        key: normalizedKey,
        size_bytes: normalizedSize,
        content_hash: normalizedHash,
        created_at: current ? current.created_at : nowISO(),
        last_accessed_at: nowISO()
      };
      index.items[normalizedKey] = item;
      index.total_bytes += normalizedSize;

      evict(index);
      saveIndex(index);
    }

    function touchItem(key) {
      const index = loadIndex();
      const item = index.items[key];
      if (!item) {
        return false;
      }
      item.last_accessed_at = nowISO();
      index.items[key] = item;
      saveIndex(index);
      return true;
    }

    function invalidateIfHashMismatch(key, expectedHash) {
      const index = loadIndex();
      const item = index.items[key];
      if (!item) {
        return;
      }
      if (item.content_hash !== expectedHash) {
        index.total_bytes = Math.max(0, index.total_bytes - Number(item.size_bytes || 0));
        delete index.items[key];
        saveIndex(index);
      }
    }

    function render() {
      const output = document.getElementById('cache-lru-output');
      if (!output) {
        return;
      }
      const index = loadIndex();
      const entries = Object.values(index.items).sort((a, b) => {
        const left = new Date(b.last_accessed_at || b.created_at || 0).getTime();
        const right = new Date(a.last_accessed_at || a.created_at || 0).getTime();
        return left - right;
      });

      output.textContent = JSON.stringify({
        limit_bytes: MAX_BYTES,
        limit_items: MAX_ITEMS,
        total_bytes: index.total_bytes,
        item_count: entries.length,
        items: entries
      }, null, 2);
    }

    window.clinicCache = {
      put: putItem,
      get: touchItem,
      invalidateIfHashMismatch,
      render,
      putFromForm: function() {
        const key = document.getElementById('cache-item-key').value;
        const size = document.getElementById('cache-item-size').value;
        const hash = document.getElementById('cache-item-hash').value;
        putItem(key, size, hash);
        render();
      }
    };

    render();
  })();
  </script>
</section>
`)
}

