package service

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"clinic-admin-suite/internal/domain"
	"clinic-admin-suite/internal/repository"
)

type PaymentService struct {
	db            *sql.DB
	payments      repository.PaymentRepository
	paymentEvents repository.PaymentEventRepository
	audit         *AuditService
	fieldCipher   *FieldCipher
	keyVersion    int
	adapters      map[string]GatewayAdapter
	logs          *StructuredLogService
}

func NewPaymentService(
	db *sql.DB,
	payments repository.PaymentRepository,
	paymentEvents repository.PaymentEventRepository,
	audit *AuditService,
	fieldCipher *FieldCipher,
	keyVersion int,
	adapters []GatewayAdapter,
	logs *StructuredLogService,
) *PaymentService {
	adapterMap := make(map[string]GatewayAdapter)
	for _, adapter := range adapters {
		if adapter == nil {
			continue
		}
		adapterMap[adapter.Name()] = adapter
	}
	return &PaymentService{
		db:            db,
		payments:      payments,
		paymentEvents: paymentEvents,
		audit:         audit,
		fieldCipher:   fieldCipher,
		keyVersion:    keyVersion,
		adapters:      adapterMap,
		logs:          logs,
	}
}

type CreatePaymentInput struct {
	Method         string
	Gateway        string
	AmountCents    int64
	Currency       string
	ShiftID        string
	PIIReference   string
	IdempotencyKey string
	ActorID        *int64
	RequestID      string
}

func (s *PaymentService) Create(ctx context.Context, input CreatePaymentInput) (*domain.Payment, error) {
	method := strings.TrimSpace(strings.ToLower(input.Method))
	if method == "" {
		return nil, fmt.Errorf("%w: payment method is required", ErrValidation)
	}
	gatewayName := strings.TrimSpace(strings.ToLower(input.Gateway))
	adapter, ok := s.adapters[gatewayName]
	if !ok {
		return nil, fmt.Errorf("%w: unsupported payment gateway", ErrValidation)
	}
	if input.AmountCents <= 0 {
		return nil, fmt.Errorf("%w: amount_cents must be positive", ErrValidation)
	}
	currency := strings.TrimSpace(strings.ToUpper(input.Currency))
	if currency == "" {
		currency = "USD"
	}
	shiftID := strings.TrimSpace(input.ShiftID)
	if shiftID == "" {
		return nil, fmt.Errorf("%w: shift_id is required", ErrValidation)
	}

	var piiEnc *string
	var piiKeyVersion *int
	if strings.TrimSpace(input.PIIReference) != "" {
		if s.fieldCipher == nil {
			return nil, fmt.Errorf("%w: field encryption key not configured", ErrValidation)
		}
		encrypted, err := s.fieldCipher.Encrypt([]byte(strings.TrimSpace(input.PIIReference)))
		if err != nil {
			return nil, err
		}
		piiEnc = &encrypted
		version := s.keyVersion
		if version <= 0 {
			version = 1
		}
		piiKeyVersion = &version
	}

	chargeResult, err := adapter.Charge(ctx, GatewayChargeRequest{
		AmountCents: input.AmountCents,
		Currency:    currency,
		Method:      method,
		Metadata: map[string]any{
			"shift_id": shiftID,
		},
	})
	if err != nil {
		return nil, fmt.Errorf("gateway charge failed: %w", err)
	}

	now := time.Now().UTC()
	status := domain.PaymentStatusSucceeded
	var failureReason *string
	if !chargeResult.Succeeded {
		status = domain.PaymentStatusFailed
		reason := strings.TrimSpace(chargeResult.FailureReason)
		if reason == "" {
			reason = "gateway_rejected"
		}
		failureReason = &reason
	}

	externalRef := strings.TrimSpace(chargeResult.ExternalRef)
	var externalRefPtr *string
	if externalRef != "" {
		externalRefPtr = &externalRef
	}

	var idemPtr *string
	if strings.TrimSpace(input.IdempotencyKey) != "" {
		v := strings.TrimSpace(input.IdempotencyKey)
		idemPtr = &v
	}

	payment := &domain.Payment{
		ExternalRef:     externalRefPtr,
		Method:          method,
		Gateway:         gatewayName,
		AmountCents:     input.AmountCents,
		Currency:        currency,
		Status:          status,
		ReceivedAt:      now,
		ShiftID:         shiftID,
		IdempotencyKey:  idemPtr,
		PIIReferenceEnc: piiEnc,
		PIIKeyVersion:   piiKeyVersion,
		FailureReason:   failureReason,
	}

	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return nil, fmt.Errorf("begin payment tx: %w", err)
	}
	defer tx.Rollback()

	if err := s.payments.CreateTx(ctx, tx, payment); err != nil {
		return nil, err
	}

	eventPayload, err := json.Marshal(map[string]any{
		"gateway_result": chargeResult.Payload,
		"status":         status,
	})
	if err != nil {
		return nil, fmt.Errorf("marshal payment event payload: %w", err)
	}

	eventType := "payment.succeeded"
	if status == domain.PaymentStatusFailed {
		eventType = "payment.failed"
	}

	if err := s.paymentEvents.CreateTx(ctx, tx, &domain.PaymentEvent{
		PaymentID: payment.ID,
		EventType: eventType,
		Payload:   string(eventPayload),
		CreatedAt: now,
	}); err != nil {
		return nil, err
	}

	resourceID := fmt.Sprintf("%d", payment.ID)
	if err := s.audit.LogEventTx(ctx, tx, AuditLogInput{
		ActorID:      input.ActorID,
		Action:       "payment.create",
		ResourceType: "payment",
		ResourceID:   resourceID,
		After: map[string]any{
			"gateway":      payment.Gateway,
			"method":       payment.Method,
			"status":       payment.Status,
			"amount_cents": payment.AmountCents,
			"currency":     payment.Currency,
			"shift_id":     payment.ShiftID,
		},
		RequestID: fallbackRequestID(input.RequestID),
	}); err != nil {
		return nil, err
	}

	if err := tx.Commit(); err != nil {
		return nil, fmt.Errorf("commit payment tx: %w", err)
	}

	if s.logs != nil {
		_ = s.logs.Log("info", "payment.create", map[string]any{
			"payment_id":    payment.ID,
			"gateway":       payment.Gateway,
			"method":        payment.Method,
			"status":        payment.Status,
			"amount_cents":  payment.AmountCents,
			"currency":      payment.Currency,
			"shift_id":      payment.ShiftID,
			"request_id":    fallbackRequestID(input.RequestID),
		})
	}

	return s.payments.GetByID(ctx, payment.ID)
}

func (s *PaymentService) List(ctx context.Context, filter repository.PaymentFilter) ([]domain.Payment, error) {
	return s.payments.List(ctx, filter)
}

func fallbackRequestID(requestID string) string {
	requestID = strings.TrimSpace(requestID)
	if requestID == "" {
		return "system"
	}
	return requestID
}

package service

import (
	"context"
	"database/sql"
	"fmt"
	"strings"
	"time"

	"clinic-admin-suite/internal/domain"
	"clinic-admin-suite/internal/repository"
)

type SettlementService struct {
	db          *sql.DB
	payments    repository.PaymentRepository
	settlements repository.SettlementRepository
	audit       *AuditService
	jobRuns     *JobRunService
	logs        *StructuredLogService
}

func NewSettlementService(
	db *sql.DB,
	payments repository.PaymentRepository,
	settlements repository.SettlementRepository,
	audit *AuditService,
	jobRuns *JobRunService,
	logs *StructuredLogService,
) *SettlementService {
	return &SettlementService{
		db:          db,
		payments:    payments,
		settlements: settlements,
		audit:       audit,
		jobRuns:     jobRuns,
		logs:        logs,
	}
}

type RunSettlementInput struct {
	ShiftID          string
	ActualTotalCents int64
	ActorID          *int64
	RequestID        string
}

type RunSettlementResult struct {
	Settlement  *domain.Settlement      `json:"settlement"`
	Items       []domain.SettlementItem `json:"items"`
	Discrepancy int64                   `json:"discrepancy_cents"`
}

func (s *SettlementService) RunShift(ctx context.Context, input RunSettlementInput) (*RunSettlementResult, error) {
	shiftID := strings.TrimSpace(input.ShiftID)
	if shiftID == "" {
		return nil, fmt.Errorf("%w: shift_id is required", ErrValidation)
	}
	if input.ActualTotalCents < 0 {
		return nil, fmt.Errorf("%w: actual_total_cents must be non-negative", ErrValidation)
	}

	startedAt := time.Now().UTC()
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return nil, fmt.Errorf("begin settlement tx: %w", err)
	}
	defer tx.Rollback()

	payments, expectedTotal, err := s.payments.ListSucceededByShiftTx(ctx, tx, shiftID)
	if err != nil {
		return nil, err
	}

	status := domain.SettlementStatusMatched
	discrepancy := input.ActualTotalCents - expectedTotal
	if discrepancy != 0 {
		status = domain.SettlementStatusDiscrepancy
	}

	finishedAt := time.Now().UTC()
	settlement := &domain.Settlement{
		ShiftID:            shiftID,
		StartedAt:          startedAt,
		FinishedAt:         finishedAt,
		Status:             status,
		ExpectedTotalCents: expectedTotal,
		ActualTotalCents:   input.ActualTotalCents,
	}

	if err := s.settlements.CreateTx(ctx, tx, settlement); err != nil {
		return nil, err
	}

	items := make([]domain.SettlementItem, 0, len(payments))
	for _, payment := range payments {
		item := domain.SettlementItem{
			SettlementID: settlement.ID,
			PaymentID:    payment.ID,
			Result:       "matched",
		}
		if status == domain.SettlementStatusDiscrepancy {
			reason := "shift_total_mismatch"
			item.Result = "discrepancy"
			item.DiscrepancyReason = &reason
		}
		if err := s.settlements.AddItemTx(ctx, tx, &item); err != nil {
			return nil, err
		}
		items = append(items, item)
	}

	if err := s.jobRuns.RecordTx(ctx, tx, JobRunInput{
		JobType:    "settlement_run",
		StartedAt:  startedAt,
		FinishedAt: finishedAt,
		Status:     status,
		Summary: map[string]any{
			"settlement_id":         settlement.ID,
			"shift_id":              shiftID,
			"expected_total_cents":  expectedTotal,
			"actual_total_cents":    input.ActualTotalCents,
			"discrepancy_cents":     discrepancy,
			"payment_count":         len(payments),
		},
	}); err != nil {
		return nil, err
	}

	if err := s.audit.LogEventTx(ctx, tx, AuditLogInput{
		ActorID:      input.ActorID,
		Action:       "settlement.run",
		ResourceType: "settlement",
		ResourceID:   fmt.Sprintf("%d", settlement.ID),
		After: map[string]any{
			"shift_id":              shiftID,
			"status":                status,
			"expected_total_cents":  expectedTotal,
			"actual_total_cents":    input.ActualTotalCents,
			"discrepancy_cents":     discrepancy,
		},
		RequestID: fallbackRequestID(input.RequestID),
	}); err != nil {
		return nil, err
	}

	if err := tx.Commit(); err != nil {
		return nil, fmt.Errorf("commit settlement tx: %w", err)
	}

	if s.logs != nil {
		_ = s.logs.Log("info", "settlement.run", map[string]any{
			"settlement_id":        settlement.ID,
			"shift_id":             shiftID,
			"status":               status,
			"expected_total_cents": expectedTotal,
			"actual_total_cents":   input.ActualTotalCents,
			"discrepancy_cents":    discrepancy,
			"request_id":           fallbackRequestID(input.RequestID),
		})
	}

	return &RunSettlementResult{
		Settlement:  settlement,
		Items:       items,
		Discrepancy: discrepancy,
	}, nil
}

