+		"exam_id":       "exam-api-3",
+		"room_id":       100,
+		"proctor_id":    999,
+		"candidate_ids": []int64{4000},
+		"start_at":      start.Add(15 * time.Minute).Format(time.RFC3339),
+		"end_at":        end.Add(15 * time.Minute).Format(time.RFC3339),
+	}
