+func countRows(t *testing.T, db *sql.DB, table string) int64 {
+	t.Helper()
+	var n int64
+	if err := db.QueryRowContext(context.Background(), "SELECT COUNT(1) FROM "+table).Scan(&n); err != nil {
+		t.Fatalf("count rows for %s: %v", table, err)
+	}
+	return n
+}

