	var env envelope
	if err := json.Unmarshal(out.Bytes(), &env); err != nil {
		t.Fatalf("unmarshal json response: %v body=%s", err, out.String())
	}

	return httpResult{status: res.StatusCode, body: out.String(), env: env}
}

