files.after:
:root {
  --ink: #1e2732;
  --muted: #5a6775;
  --paper: #f5f7fa;
  --panel: #ffffff;
  --line: #dbe3ec;
  --accent: #0e8f83;
  --accent-strong: #0a6f65;
  --warn: #b04f2d;
  --shadow: 0 14px 32px rgba(22, 40, 62, 0.12);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Segoe UI", "Trebuchet MS", sans-serif;
  color: var(--ink);
  background: linear-gradient(135deg, #edf5ff 0%, #f8efe5 40%, #f3fbf8 100%);
  min-height: 100vh;
}

.backdrop {
  position: fixed;
  inset: 0;
  background: radial-gradient(circle at 20% 10%, rgba(14, 143, 131, 0.16), transparent 48%),
              radial-gradient(circle at 85% 20%, rgba(222, 128, 66, 0.14), transparent 40%);
  pointer-events: none;
}

.shell {
  width: min(1200px, 95vw);
  margin: 1.5rem auto 2rem;
  position: relative;
  z-index: 1;
}

.hero {
  display: flex;
  justify-content: space-between;
  align-items: start;
  gap: 1rem;
  margin-bottom: 1rem;
}

.kicker {
  margin: 0;
  color: var(--accent-strong);
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-size: 0.75rem;
}

h1 {
  margin: 0.35rem 0 0.5rem;
  font-size: clamp(1.4rem, 2vw, 2.2rem);
}

.subtitle {
  margin: 0;
  color: var(--muted);
}

.session-chip {
  background: #132a3f;
  color: #f7fbff;
  padding: 0.45rem 0.8rem;
  border-radius: 999px;
  font-size: 0.85rem;
  white-space: nowrap;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 1rem;
  box-shadow: var(--shadow);
  margin-top: 1rem;
}

.hidden {
  display: none;
}

.top-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 0.8rem;
}

button,
input,
select {
  font: inherit;
}

button {
  border: 1px solid #c4d3e3;
  background: #f2f8ff;
  color: #153041;
  padding: 0.45rem 0.75rem;
  border-radius: 9px;
  cursor: pointer;
}

button.active,
button:hover {
  background: #dff4f1;
  border-color: #99d8d0;
}

button.warn {
  border-color: #efc1af;
  background: #fff2ec;
  color: var(--warn);
}

.view {
  display: none;
}

.view.active {
  display: block;
}

.grid {
  display: grid;
  gap: 0.9rem;
}

.grid.two {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.card {
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 0.85rem;
  background: #fff;
}

.row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.7rem;
}

.stack,
.stack-form {
  display: grid;
  gap: 0.6rem;
}

label {
  display: grid;
  gap: 0.35rem;
  font-size: 0.92rem;
}

input,
select {
  border: 1px solid #ccd8e4;
  border-radius: 8px;
  padding: 0.45rem 0.55rem;
  background: #fdfefe;
}

.hint {
  color: var(--muted);
  font-size: 0.9rem;
}

.output {
  margin: 0;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 0.7rem;
  max-height: 300px;
  overflow: auto;
  white-space: pre-wrap;
}

.occupancy-host {
  margin-top: 0.7rem;
}

.exercise-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.7rem;
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 0.5rem 0.7rem;
}

.favorite {
  color: #9f5f00;
  background: #fff5d7;
  border-color: #f4d791;
}

@media (max-width: 900px) {
  .grid.two {
    grid-template-columns: 1fr;
  }
  .hero {
    flex-direction: column;
  }
}

