+			continue
+		}
+		start := time.Now().UTC()
+		err := s.runSchedule(ctx, schedule)
+		finish := time.Now().UTC()
+
+		status := "completed"
+		summary := map[string]any{"schedule_id": schedule.ID, "report_type": schedule.ReportType}
+		if err != nil {
+			status = "failed"
+			summary["error"] = err.Error()
+		}
