+		return handleServiceError(c, err, "Failed to create report schedule")
+	}
+
+	return httpx.OK(c, fiber.StatusCreated, fiber.Map{"report_schedule": item})
+}
+
+func (h *GovernanceHandler) ListReportSchedules(c *fiber.Ctx) error {
