+	}
+	return h.PanelReports(c)
+}
+
+func parseIDCSV(raw string) []int64 {
+	parts := strings.Split(raw, ",")
+	out := make([]int64, 0, len(parts))
+	for _, part := range parts {
+		v, err := strconv.ParseInt(strings.TrimSpace(part), 10, 64)
+		if err == nil && v > 0 {
+			out = append(out, v)
+		}
+	}
+	return out
+}

