package handler

import (
	"fmt"
	"html"
	"sort"
	"strconv"
	"strings"
	"time"

	"clinic-admin-suite/internal/api/middleware"
	"clinic-admin-suite/internal/config"
	"clinic-admin-suite/internal/repository"
	"clinic-admin-suite/internal/service"

	"github.com/gofiber/fiber/v2"
)

type AppPagesHandler struct {
	config      config.Config
	auth        *service.AuthService
	admissions  *service.AdmissionsService
	exercises   *service.ExerciseService
	favorites   *service.ExerciseFavoriteService
	care        *service.CareService
	templates   *service.ExamTemplateService
	payments    *service.PaymentService
	settlements *service.SettlementService
	reports     *service.ReportService
}

func NewAppPagesHandler(cfg config.Config, auth *service.AuthService, admissions *service.AdmissionsService, exercises *service.ExerciseService, favorites *service.ExerciseFavoriteService, care *service.CareService, templates *service.ExamTemplateService, payments *service.PaymentService, settlements *service.SettlementService, reports *service.ReportService) *AppPagesHandler {
	return &AppPagesHandler{
		config:      cfg,
		auth:        auth,
		admissions:  admissions,
		exercises:   exercises,
		favorites:   favorites,
		care:        care,
		templates:   templates,
		payments:    payments,
		settlements: settlements,
		reports:     reports,
	}
}

func (h *AppPagesHandler) LoginPage(c *fiber.Ctx) error {
	c.Type("html", "utf-8")
	return c.SendString(`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>CareOps Login</title><link rel="stylesheet" href="/assets/app.css"></head><body><main class="shell"><section class="panel"><h1>CareOps Login</h1><p class="hint">Local-only authentication. Session expires after 15 minutes inactivity.</p><form method="post" action="/login" class="stack-form"><label>Username<input name="username" required></label><label>Password<input name="password" type="password" required></label><button type="submit">Sign In</button></form></section></main></body></html>`)
}

func (h *AppPagesHandler) LoginSubmit(c *fiber.Ctx) error {
	username := strings.TrimSpace(c.FormValue("username"))
	password := c.FormValue("password")
	result, err := h.auth.Login(c.UserContext(), service.LoginInput{
		Username:  username,
		Password:  password,
		RequestID: c.Get("X-Request-ID"),
		IP:        c.IP(),
		UserAgent: c.Get("User-Agent"),
	})
	if err != nil {
		return c.Status(fiber.StatusUnauthorized).SendString("invalid credentials")
	}

	c.Cookie(&fiber.Cookie{Name: h.config.SessionCookieName, Value: result.Token, Path: "/", Expires: result.ExpiresAt, HTTPOnly: true, Secure: h.config.CookieSecure, SameSite: "Strict"})
	return c.Redirect("/app", fiber.StatusSeeOther)
}

func (h *AppPagesHandler) Logout(c *fiber.Ctx) error {
	c.Cookie(&fiber.Cookie{Name: h.config.SessionCookieName, Value: "", Path: "/", Expires: time.Unix(0, 0), HTTPOnly: true, Secure: h.config.CookieSecure, SameSite: "Strict"})
	return c.Redirect("/login", fiber.StatusSeeOther)
}

func (h *AppPagesHandler) AppShell(c *fiber.Ctx) error {
	authCtx, _ := middleware.CurrentAuth(c)
	username := ""
	if authCtx != nil && authCtx.User != nil {
		username = authCtx.User.Username
	}

	body := `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>CareOps Clinic Suite</title><link rel="stylesheet" href="/assets/app.css"><script src="/assets/htmx-lite.js" defer></script></head><body><main class="shell"><header class="hero"><div><p class="kicker">CareOps Clinic Administration Suite</p><h1>Server-Rendered Operations Console</h1><p class="subtitle">HTMX-driven workflows for occupancy, quality checkpoints, alerts, scheduling, finance, and governance.</p></div><div class="session-chip">` + html.EscapeString(username) + `</div></header><section class="panel"><div class="top-nav"><button hx-get="/ui/panels/overview" hx-target="#panel">Overview</button><button hx-get="/ui/panels/occupancy" hx-target="#panel">Occupancy</button><button hx-get="/ui/panels/care" hx-target="#panel">Quality and Alerts</button><button hx-get="/ui/panels/exercises" hx-target="#panel">Exercises</button><button hx-get="/ui/panels/scheduling" hx-target="#panel">Scheduling</button><button hx-get="/ui/panels/finance" hx-target="#panel">Finance</button><button hx-get="/ui/panels/reports" hx-target="#panel">Reports and Audit</button><form method="post" action="/logout"><button type="submit" class="warn">Logout</button></form></div><div id="htmx-indicator" class="hint" style="display:none">Loading...</div><div id="panel" hx-get="/ui/panels/overview" hx-trigger="load" hx-target="#panel"></div></section></main></body></html>`
	c.Type("html", "utf-8")
	return c.SendString(body)
}

func (h *AppPagesHandler) PanelOverview(c *fiber.Ctx) error {
	ops, _ := h.reports.OpsSummary(c.UserContext())
	careSummary, _ := h.care.Dashboard(c.UserContext())
	if ops == nil {
		ops = &service.OpsSummary{}
	}
	if careSummary == nil {
		careSummary = &struct {
			CheckpointCount int64
			AlertOpenCount  int64
			AlertHighCount  int64
		}{
			CheckpointCount: 0,
			AlertOpenCount:  0,
			AlertHighCount:  0,
		}
	}

	return c.SendString(`<section class="view active"><div class="grid two"><article class="card"><h3>Operations Summary</h3><pre class="output">active_admissions: ` + strconv.FormatInt(ops.ActiveAdmissions, 10) + `
occupied_beds: ` + strconv.FormatInt(ops.OccupiedBeds, 10) + `
open_work_orders: ` + strconv.FormatInt(ops.OpenWorkOrders, 10) + `
payments_today_count: ` + strconv.FormatInt(ops.PaymentsTodayCount, 10) + `
payments_today_net_cents: ` + strconv.FormatInt(ops.PaymentsTodayNetCents, 10) + `
upcoming_exams_48h: ` + strconv.FormatInt(ops.UpcomingExams48h, 10) + `</pre></article><article class="card"><h3>Care Quality Visibility</h3><pre class="output">checkpoint_count: ` + strconv.FormatInt(careSummary.CheckpointCount, 10) + `
open_alerts: ` + strconv.FormatInt(careSummary.AlertOpenCount, 10) + `
high_or_critical_open_alerts: ` + strconv.FormatInt(careSummary.AlertHighCount, 10) + `</pre></article></div></section>`)
}

func (h *AppPagesHandler) PanelOccupancy(c *fiber.Ctx) error {
	items, err := h.admissions.OccupancyBoard(c.UserContext())
	if err != nil {
		return c.Status(fiber.StatusInternalServerError).SendString("<div class='card'>Failed to load occupancy board</div>")
	}
	var b strings.Builder
	b.WriteString(`<section class="view active"><article class="card"><h3>Occupancy Board</h3><div class="stack">`)
	if len(items) == 0 {
		b.WriteString(`<p class="hint">No occupancy records found.</p>`)
	}
	for _, item := range items {
		b.WriteString(`<div class="exercise-row"><div><strong>` + html.EscapeString(item.WardName) + ` / ` + html.EscapeString(item.BedCode) + `</strong><div>` + html.EscapeString(item.Status) + `</div></div><div>` + html.EscapeString(item.PatientName) + `</div></div>`)
	}
	b.WriteString(`</div></article></section>`)
	return c.SendString(b.String())
}

func (h *AppPagesHandler) PanelExercises(c *fiber.Ctx) error {
	authCtx, _ := middleware.CurrentAuth(c)
	items, err := h.exercises.List(c.UserContext(), repository.ExerciseFilter{})
	if err != nil {
		return c.Status(fiber.StatusInternalServerError).SendString("<div class='card'>Failed to load exercises</div>")
	}
	favorites := map[int64]struct{}{}
	if authCtx != nil && authCtx.User != nil {
		favorites, _ = h.favorites.ListIDs(c.UserContext(), authCtx.User.ID)
	}
	var b strings.Builder
	b.WriteString(`<section class="view active"><article class="card"><h3>Exercise Browse and Favorites</h3><p class="hint">Server-rendered list with HTMX toggle actions.</p><div class="stack">`)
	if len(items) == 0 {
		b.WriteString(`<p class="hint">No exercises available.</p>`)
	}
	for _, item := range items {
		_, favored := favorites[item.ID]
		btn := "Add Favorite"
		cls := ""
		if favored {
			btn = "Favorited"
			cls = "favorite"
		}
		b.WriteString(`<div class="exercise-row"><div><strong>` + html.EscapeString(item.Title) + `</strong><div>` + html.EscapeString(item.Difficulty) + `</div></div><button class="` + cls + `" hx-post="/ui/exercises/` + strconv.FormatInt(item.ID, 10) + `/favorite" hx-target="#panel">` + btn + `</button></div>`)
	}
	b.WriteString(`</div><div class="row"><button hx-get="/ui/cache/lru" hx-target="#cache-fragment">Load Cache Simulator</button><button class="warn" onclick="window.clearClinicDeviceCache()">Clear Device Cache</button></div><div id="cache-fragment" class="stack"></div></article></section>`)
	return c.SendString(b.String())
}

func (h *AppPagesHandler) ToggleFavorite(c *fiber.Ctx) error {
	authCtx, ok := middleware.CurrentAuth(c)
	if !ok || authCtx.User == nil {
		return c.Status(fiber.StatusUnauthorized).SendString("authentication required")
	}
	exerciseID, err := strconv.ParseInt(c.Params("exercise_id"), 10, 64)
	if err != nil || exerciseID <= 0 {
		return c.Status(fiber.StatusUnprocessableEntity).SendString("invalid exercise_id")
	}
	_, err = h.favorites.Toggle(c.UserContext(), authCtx.User.ID, exerciseID)
	if err != nil {
		return c.Status(fiber.StatusInternalServerError).SendString("failed to toggle favorite")
	}
	return h.PanelExercises(c)
}

func (h *AppPagesHandler) PanelCare(c *fiber.Ctx) error {
	checkpoints, _ := h.care.ListCheckpoints(c.UserContext(), service.CareCheckpointFilter{})
	alerts, _ := h.care.ListAlerts(c.UserContext(), service.AlertEventFilter{})

	var b strings.Builder
	b.WriteString(`<section class="view active"><div class="grid two"><article class="card"><h3>Record Care Quality Checkpoint</h3><form class="stack-form" hx-post="/ui/care/checkpoints" hx-target="#panel"><label>Resident ID<input name="resident_id" type="number" required></label><label>Checkpoint Type<input name="checkpoint_type" required></label><label>Status<select name="status"><option value="pass">pass</option><option value="watch">watch</option><option value="fail">fail</option></select></label><label>Notes<input name="notes"></label><button type="submit">Save Checkpoint</button></form></article><article class="card"><h3>Record Alert Event</h3><form class="stack-form" hx-post="/ui/care/alerts" hx-target="#panel"><label>Resident ID<input name="resident_id" type="number" required></label><label>Alert Type<input name="alert_type" required></label><label>Severity<select name="severity"><option>low</option><option>medium</option><option>high</option><option>critical</option></select></label><label>State<select name="state"><option>open</option><option>acknowledged</option><option>resolved</option></select></label><label>Message<input name="message" required></label><button type="submit">Save Alert</button></form></article></div>`)

	b.WriteString(`<article class="card"><h3>Checkpoint Log</h3><div class="stack">`)
	if len(checkpoints) == 0 {
		b.WriteString(`<p class="hint">No checkpoints found.</p>`)
	}
	for _, item := range checkpoints {
