	_, err := h.templates.GenerateDraft(c.UserContext(), service.GenerateDraftInput{TemplateID: templateID, WindowID: windowID, StartAt: startAt, ActorID: currentActorIDFromContext(c), RequestID: c.Get("X-Request-ID")})
