	_, err := h.templates.AdjustDraft(c.UserContext(), service.AdjustDraftInput{DraftID: draftID, StartAt: startAt, EndAt: endAt, ActorID: currentActorIDFromContext(c), RequestID: c.Get("X-Request-ID")})
