const { test, expect } = require('@playwright/test')

async function login(page) {
  await page.goto('/login')
  await page.getByLabel('Username').fill('admin')
  await page.getByLabel('Password').fill('AdminPassword1!')
  await page.getByRole('button', { name: 'Sign In' }).click()
  await expect(page).toHaveURL(/\/app$/)
  await expect(page.getByText('Server-Rendered Operations Console')).toBeVisible()
}

test('login/session and occupancy overview flow', async ({ page, request }) => {
  await login(page)

  await request.post('/api/v1/wards', { data: { name: 'E2E Ward' }, headers: { 'Idempotency-Key': 'e2e-ward-1' } })
  const wardRes = await request.get('/api/v1/wards')
  const wardBody = await wardRes.json()
  const wardID = wardBody.data.wards.find((w) => w.name === 'E2E Ward').id

  const patientRes = await request.post('/api/v1/patients', { data: { mrn: 'E2E-MRN-1', name: 'E2E Resident' }, headers: { 'Idempotency-Key': 'e2e-patient-1' } })
  const patientBody = await patientRes.json()
  const patientID = patientBody.data.patient.id

  const bedRes = await request.post('/api/v1/beds', { data: { ward_id: wardID, bed_code: 'E2E-01' }, headers: { 'Idempotency-Key': 'e2e-bed-1' } })
  const bedBody = await bedRes.json()
  const bedID = bedBody.data.bed.id

  await request.post('/api/v1/admissions', { data: { patient_id: patientID, bed_id: bedID }, headers: { 'Idempotency-Key': 'e2e-admission-1' } })

  await page.getByRole('button', { name: 'Occupancy' }).click()
  await expect(page.locator('#panel')).toContainText('Occupancy Board')
  await expect(page.locator('#panel')).toContainText('E2E-01')

  await page.locator('form[action="/logout"] button').click()
  await expect(page).toHaveURL(/\/login$/)
})

test('exercise favorite and cache clear', async ({ page, request }) => {
  await login(page)

  await request.post('/api/v1/exercises', {
    data: {
      title: 'E2E Squat',
      description: 'exercise for e2e',
      difficulty: 'beginner',
      tags: ['legs'],
      equipment: ['none'],
      contraindications: [],
      body_regions: ['lower body']
    },
    headers: { 'Idempotency-Key': 'e2e-exercise-1' }
  })

  await page.getByRole('button', { name: 'Exercises' }).click()
  await expect(page.locator('#panel')).toContainText('Exercise Browse and Favorites')
  await page.getByRole('button', { name: 'Add Favorite' }).first().click()
  await expect(page.locator('#panel')).toContainText('Favorited')
  await page.getByRole('button', { name: 'Load Cache Simulator' }).click()
  await expect(page.locator('#panel')).toContainText('Client LRU Cache Simulator')
  await page.getByRole('button', { name: 'Clear Device Cache' }).click()
})

test('scheduling conflict and publish, finance, reports', async ({ page, request }) => {
  await login(page)

  const start = new Date(Date.now() + 4 * 60 * 60 * 1000)
  const end = new Date(start.getTime() + 3 * 60 * 60 * 1000)
  const startRFC = start.toISOString().replace('.000', '')
  const endRFC = end.toISOString().replace('.000', '')

  await page.getByRole('button', { name: 'Scheduling' }).click()
  await page.getByLabel('Title').fill('E2E Template')
  await page.getByLabel('Subject').fill('Math')
  await page.getByLabel('Duration Minutes').fill('90')
  await page.getByLabel('Room ID').fill('801')
  await page.getByLabel('Proctor ID').fill('901')
  await page.getByLabel('Candidate IDs').fill('7001,7002')
  await page.getByLabel('Window Start (RFC3339)').fill(startRFC)
  await page.getByLabel('Window End (RFC3339)').fill(endRFC)
  await page.getByRole('button', { name: 'Save Template' }).click()
  await expect(page.locator('#panel')).toContainText('Exam Templates')

  const templatesRes = await request.get('/api/v1/exam-templates')
  const templatesBody = await templatesRes.json()
  const tpl = templatesBody.data.exam_templates[0]
  const templateID = tpl.id
  const windowID = tpl.windows[0].id

  await request.post('/api/v1/exam-schedules', {
    data: {
      exam_id: 'conflict-existing',
      room_id: tpl.room_id,
      proctor_id: tpl.proctor_id,
      candidate_ids: [7001],
      start_at: startRFC,
      end_at: new Date(start.getTime() + 90 * 60 * 1000).toISOString().replace('.000', '')
    },
    headers: { 'Idempotency-Key': 'e2e-existing-schedule' }
  })

  await page.getByLabel('Template ID').fill(String(templateID))
  await page.getByLabel('Window ID').fill(String(windowID))
  await page.getByRole('button', { name: 'Generate Draft' }).click()
  await expect(page.locator('#panel')).toContainText('conflicts')

  const draftsRes = await request.get('/api/v1/exam-session-drafts')
  const draftsBody = await draftsRes.json()
  const draft = draftsBody.data.exam_session_drafts[0]

  const adjustedStart = new Date(end.getTime() + 30 * 60 * 1000)
  const adjustedEnd = new Date(adjustedStart.getTime() + 90 * 60 * 1000)
  await request.post(`/api/v1/exam-session-drafts/${draft.id}/adjust`, {
    data: { start_at: adjustedStart.toISOString().replace('.000', ''), end_at: adjustedEnd.toISOString().replace('.000', '') },
    headers: { 'Idempotency-Key': 'e2e-draft-adjust' }
  })
  await request.post(`/api/v1/exam-session-drafts/${draft.id}/publish`, { headers: { 'Idempotency-Key': 'e2e-draft-publish' } })

  await page.getByRole('button', { name: 'Finance' }).click()
  await page.getByLabel('Amount Cents').fill('20000')
  await page.getByRole('button', { name: 'Capture Payment' }).click()
  await expect(page.locator('#panel')).toContainText('Recent Payments')

  const paymentsRes = await request.get('/api/v1/payments')
  const paymentsBody = await paymentsRes.json()
  const paymentID = paymentsBody.data.payments[0].id
  await page.getByLabel('Payment ID').fill(String(paymentID))
  await page.getByLabel('Reason').fill('e2e_refund')
  await page.getByRole('button', { name: 'Submit Refund' }).click()

  await page.getByRole('button', { name: 'Reports and Audit' }).click()
  await expect(page.locator('#panel')).toContainText('Audit Search')
  await page.getByRole('button', { name: 'Save Schedule' }).click()
  await expect(page.locator('#panel')).toContainText('Config Versioning and Rollback')
})

