}

func computeAuditHash(hashPrev *string, occurredAt time.Time, actorID *int64, action, resourceType, resourceID string, beforeJSON, afterJSON *string, requestID string) string {
	base := ""
	if hashPrev != nil {
		base = *hashPrev
	}

	actor := ""
	if actorID != nil {
		actor = strconv.FormatInt(*actorID, 10)
	}

