  const draftsBody = await draftsRes.json();
  const draft = draftsBody.data.exam_session_drafts[0];
  expect(draft.conflicts.length).toBeGreaterThan(0);

  const adjustedStart = new Date(end.getTime() + 30 * 60 * 1000);
