	c.Cookie(&fiber.Cookie{Name: h.config.SessionCookieName, Value: "", Path: "/", Expires: time.Unix(0, 0), HTTPOnly: true, Secure: h.config.CookieSecure, SameSite: "Strict"})
	return c.Redirect("/login", fiber.StatusSeeOther)
}

