		return c.Redirect("/login", fiber.StatusSeeOther)
	}
	user, _, err := h.auth.AuthenticateToken(c.UserContext(), rawToken)
	if err != nil || user == nil {
		return c.Redirect("/login", fiber.StatusSeeOther)
